<section id="news-draft-review" class="news-editor-section news-draft-review" aria-labelledby="news-draft-review-title" hidden>
  <header><div><h3 id="news-draft-review-title">ตรวจทานร่างข่าว</h3><p class="news-field-help" id="news-draft-source"></p></div><button class="btn ghost" id="news-draft-dismiss" type="button">ปิดร่าง</button></header>
  <p class="news-review-note">ร่างนี้ยังไม่เปลี่ยนข้อความในฟอร์ม ตรวจสอบชื่อทีม คะแนน และสถานะผลจากข้อมูลอ้างอิงก่อนนำมาใช้</p>
  <label>หัวข้อร่าง<input id="news-draft-title"></label>
  <label>คำโปรยร่าง<textarea id="news-draft-excerpt" rows="3"></textarea></label>
  <label>เนื้อหาร่าง<textarea id="news-draft-body" rows="7"></textarea></label>
  <label class="checkbox-line news-draft-verify" id="news-draft-verify-row" hidden><input type="checkbox" id="news-draft-verified"> ตรวจสอบชื่อ คะแนน และข้อเท็จจริงกับข้อมูลการแข่งขันแล้ว</label>
  <div class="actions"><button class="btn primary" id="news-draft-apply" type="button"><i data-lucide="check"></i><span>นำร่างมาใช้</span></button></div>
</section>
